`beforeList`  и  `afterList`  добавляют контент в начало и конец списка. :::note
Слоты закреплены: скроллится только список,  `listMaxHeight`  ограничивает его, а не весь попап.
::: ```tsx
import React, { useState } from 'react';
import { BodyXS, Divider, LinkButton, Select, TabItem, Tabs } from '@salutejs/sdds-finai';

export function App() {
    const regions = [
        { value: 'all', label: 'Все' },
        { value: 'europe', label: 'Европа' },
        { value: 'asia', label: 'Азия' },
    ];

    const cities = [
        { value: 'berlin', label: 'Берлин', region: 'europe' },
        { value: 'paris', label: 'Париж', region: 'europe' },
        { value: 'rome', label: 'Рим', region: 'europe' },
        { value: 'madrid', label: 'Мадрид', region: 'europe' },
        { value: 'prague', label: 'Прага', region: 'europe' },
        { value: 'tokyo', label: 'Токио', region: 'asia' },
        { value: 'seoul', label: 'Сеул', region: 'asia' },
        { value: 'bangkok', label: 'Бангкок', region: 'asia' },
        { value: 'shanghai', label: 'Шанхай', region: 'asia' },
    ];

    const [region, setRegion] = useState('all');
    const [value, setValue] = useState([]);

    const items = cities.filter((item) => region === 'all' || item.region === region);

    return (
        <div style={{ display: 'flex', flexDirection: 'column', maxWidth: '350px', height: '420px' }}>
            <Select
                multiselect
                items={items}
                value={value}
                onChange={setValue}
                label="Label"
                placeholder="Placeholder"
                listMaxHeight="200px"
                beforeList={
                    <Tabs view="filled" size="xs" stretch>
                        {regions.map((item) => (
                            <TabItem
                                key={item.value}
                                view="secondary"
                                size="xs"
                                tabIndex={0}
                                selected={item.value === region}
                                onClick={() => setRegion(item.value)}
                            >
                                {item.label}
                            </TabItem>
                        ))}
                    </Tabs>
                }
                afterList={
                    <>
                        <Divider />
                        <div
                            style={{
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'space-between',
                                gap: '0.5rem',
                                padding: '0.5rem 0.75rem',
                            }}
                        >
                            <BodyXS style={{ color: 'var(--text-secondary)' }}>
                                {`Выбрано: ${value.length}`}
                            </BodyXS>
                            <LinkButton
                                size="xs"
                                view="accent"
                                text="Сбросить"
                                disabled={!value.length}
                                onClick={() => setValue([])}
                            />
                        </div>
                    </>
                }
            />
        </div>
    );
}
```

## Взаимодействие с disabled-элементами Взаимодействие с disabled-элементами Изнутри компонента взаимодействие с disabled-элементами  невозможно . Ниже представлены примеры с  `selected`  и  `unselected`  disabled-элементом. ```tsx
    import React, { useState } from 'react';
    import { Select } from '@salutejs/sdds-finai';

    export function App() {
        const items = [
            {
                value: 'north_america',
                label: 'Северная Америка',
            },
            {
                value: 'south_america',
                label: 'Южная Америка',
                items: [
                    {
                        value: 'brazil',
                        label: 'Бразилия',
                        disabled: true,
                    },
                    {
                        value: 'argentina',
                        label: 'Аргентина',
                    },
                ],
            },
        ];

        const [value, setValue] = useState(['brazil']);

        return (
            <div style={{ display: 'flex', flexDirection: 'column', maxWidth: '350px', height: '300px' }}>
                <Select
                    multiselect
                    label="Label"
                    placeholder="Placeholder"
                    items={items}
                />

                <Select
                    multiselect
                    label="Label"
                    placeholder="Placeholder"
                    items={items}
                    value={value}
                    onChange={setValue}
                    isTargetAmount
                />
            </div>
        );
    }
```

## Использование с React Hook Form и нативной формой Использование с React Hook Form и нативной формой :::caution Использование атрибута  `name` 
Используйте свойство  `name`  только когда это необходимо. Если  `value`  не передан, компонент работает в native-режиме и  `onChange`  получает native-like event.
::: Работа с  `react-hook-form`  через  `register` . ```tsx
import React from 'react';
import { useForm, SubmitHandler } from 'react-hook-form';
import { Select, Button } from '@salutejs/sdds-finai';

export function App() {
    type Inputs = {
        select: string,
        selectMulti: string[]
    }

    const { register, handleSubmit } = useForm<Inputs>({
        defaultValues: {
            select: 'north_america',
            selectMulti: ['brazil']
        }
    });

    const onSubmit: SubmitHandler<Inputs> = (data) => {
        console.log(data);
    };

    const items = [
